                    bits |= (long)f.Bytes[i] << (8 * i);
                }
                if (field.Type == TypeDouble)
                {
                    return BitConverter.Int64BitsToDouble(bits);
                }
                return bits;
            }
            case 5:
            {
                int bits = 0;
                for (int i = 0; i < 4; i++)
                {
                    bits |= f.Bytes[i] << (8 * i);
                }
                if (field.Type == TypeFloat)
                {
                    return BitConverter.Int32BitsToSingle(bits);
                }
                return (long)(uint)bits;
