            default:
                if (field.Type == TypeString)
                {
                    return System.Text.Encoding.UTF8.GetString(f.Bytes);
                }
                if (field.Type == TypeMessage)
                {
                    return DecodeGeneric(fileModel.Messages[field.TypeName], f.Bytes, fileModel);
                }
                return f.Bytes;
